  function replaceAllFix() {
    (function () {
      var clientReplaceAll = String.prototype.replaceAll;

      // Preserve the client's regex-based implementation.
      Object.defineProperty(String.prototype, 'replaceAllReg', {
        configurable: true,
        writable: true,
        value: clientReplaceAll,
      });

      function escapeRegExp(value) {
        return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      }

      Object.defineProperty(String.prototype, 'replaceAll', {
        configurable: true,
        writable: true,
        value: function (search, replacement) {
          // Preserve the client's behaviour for actual regular expressions.
          if (search instanceof RegExp) {
            return clientReplaceAll.call(this, search, replacement);
          }

          search = String(search);

          try {
            // Preserve the client's regex-string behaviour when valid.
            new RegExp(search, 'g');
            return clientReplaceAll.call(this, search, replacement);
          } catch (error) {
            if (!(error instanceof SyntaxError)) {
              throw error;
            }

            // Invalid regex strings such as "(" become literal searches.
            return String(this).replace(new RegExp(escapeRegExp(search), 'g'), replacement);
          }
        },
      });
    })();
  }
 
 


     
